{"command":"python3 - <<'PY'
import csv
for f in ['data/pickup_zones.csv','data/carriers.csv','data/tariff_lanes.csv']:
 print('\n---',f,'---')
 with open(f,newline='') as x:
  for row in csv.DictReader(x):
   if f.endswith('pickup_zones.csv') and row.get('zone')=='70': print(row)
   elif f.endswith('carriers.csv') and (row.get('kind')=='trucker' and '70' in row.get('serves','').split() or row.get('kind')=='airline' and 'PVG' in row.get('serves','').split()): print(row)
   elif f.endswith('tariff_lanes.csv') and row.get('destination')=='PVG': print(row)
PY
