  pageId: number,
  /** Maximum number of requests to return. When omitted, returns all requests. @integer @exclusiveMinimum 0 */
  pageSize?: number,
  /**
   * Page number to return (0-based). When omitted, returns the first page. Ignored unless pageSize is set.
   * @integer @minimum 0
   */
  pageIdx?: number,
  /**
   * Filter requests to only return requests of the specified resource types. When omitted or empty, returns all requests.
   */
  resourceTypes?: Array<"document" | "stylesheet" | "image" | "media" | "font" | "script" | "texttrack" | "xhr" | "fetch" | "prefetch" | "eventsource" | "manifest" | "signedexchange" | "ping" | "cspviolationreport" | "preflight" | "fedcm" | "other">,
  /** Set to true to return the preserved requests over the last 3 navigations. @default false */
