   */
  logpoints: Array<string>,
}): Promise<unknown>"},{"path":"tools["chrome-devtools"].get_console_message","description":"Gets a console message by its ID. You can get all messages by calling list_console_messages.","signature":"tools["chrome-devtools"].get_console_message({
